import * as source from '#compiler/adapters/avatar/source'

import { AVATAR_MODULE_TYPE, AVATAR_PLUGIN_ID } from '@open-pencil/core/plugins'

import { REACT_MODULE_POSITIONED_HOST_SOURCE } from './runtime-source'
import type { ReactModuleAdapter, ReactModuleRuntimeOptions } from './types'

export function buildOpenPencilAvatarComponent(options?: ReactModuleRuntimeOptions): string {
  return `/// <reference types="vite/client" />
// Auto-generated by OpenPencil compiler. Do not edit by hand.
import {useId,useState,type HTMLAttributes} from 'react'
${source.avatarAssetImports(options?.bundledAssetPaths)}
${source.AVATAR_CONFIG_SOURCE}
${source.AVATAR_PRESENTATION_SOURCE}
export interface OpenPencilAvatarProps extends HTMLAttributes<HTMLDivElement> {config:OpenPencilAvatarConfig}
export default function OpenPencilAvatar({config,className,style,children,...hostProps}:OpenPencilAvatarProps){
 const visual=avatarPresentation(config), clip=useId(), [failed,setFailed]=useState<string>()
 const showImage=!!visual.src && failed!==visual.src
${REACT_MODULE_POSITIONED_HOST_SOURCE}
 return <div {...hostProps} className={className} style={hostStyle} data-openpencil-avatar="" role="img" aria-label={config.name}>
 <style>{${JSON.stringify(source.AVATAR_STYLE_SOURCE)}}</style>
 <svg data-avatar-surface="" aria-hidden="true" focusable="false" viewBox={'0 0 '+visual.size+' '+visual.size}
   style={{maxWidth:visual.size,maxHeight:visual.size}} preserveAspectRatio="xMidYMid meet">
  <defs><clipPath id={clip}><rect width={visual.size} height={visual.size} rx={visual.radius}/></clipPath></defs>
  <g clipPath={'url(#'+clip+')'}><rect width={visual.size} height={visual.size} rx={visual.radius} fill={config.backgroundColor}/>
  {showImage ? <image key={visual.src} data-avatar-image="" href={visual.src} width={visual.size} height={visual.size}
    preserveAspectRatio={visual.fit} opacity={config.imageOpacity ?? 1} onError={()=>setFailed(visual.src)}/>
  : <text data-avatar-fallback="" x={visual.size/2} y={visual.size/2} textAnchor="middle" dominantBaseline="central"
    fontSize={visual.fontSize} fill={config.textColor}>{visual.text}</text>}
  {config.borderWidth>0 && <rect x={config.borderWidth/2} y={config.borderWidth/2} width={visual.size-config.borderWidth}
    height={visual.size-config.borderWidth} rx={Math.max(0,visual.radius-config.borderWidth/2)} fill="none" stroke={config.borderColor} strokeWidth={config.borderWidth}/>}
  </g></svg>{children}</div>
}`
}
export const AVATAR_REACT_MODULE_ADAPTER: ReactModuleAdapter = Object.freeze({
  pluginId: AVATAR_PLUGIN_ID,
  moduleType: AVATAR_MODULE_TYPE,
  componentName: 'OpenPencilAvatar',
  runtimePath: 'src/__openpencil_avatar.tsx',
  rootImportPath: './__openpencil_avatar',
  nestedImportPath: '../__openpencil_avatar',
  buildRuntime: buildOpenPencilAvatarComponent
})
